index bf487a7..9cdf13c 100644
--- a/search.mjs
+++ b/search.mjs
@@ -1,5 +1,28 @@
 // Isolated reproduction of article-search edge cases, not production code.
 export function searchArticles(rows, query) {
-  const needle = query.trim().toLowerCase();
-  return rows.filter(row => `${row.title || ''} ${row.summary || ''}`.toLowerCase().includes(needle));
+  const needle = String(query ?? '').normalize('NFKC').trim().toLowerCase();
+  if (!needle || !Array.isArray(rows)) return [];
+
+  const seenIds = new Set();
+  const matches = [];
+
+  for (const row of rows) {
+    if (!row || typeof row !== 'object') continue;
+    if (typeof row.id !== 'string' || row.id.length === 0) continue;
+
+    const haystack = [
+      row.title ?? '',
+      row.title_zh ?? '',
+      row.summary ?? '',
+      row.summary_zh ?? '',
+    ].join(' ').normalize('NFKC').toLowerCase();
+
+    if (!haystack.includes(needle)) continue;
+    if (seenIds.has(row.id)) continue;
+
+    seenIds.add(row.id);
+    matches.push(row);
+  }
+
+  return matches;
 }
